/bin/zsh -lc "node --input-type=module <<'NODE'
import { createServer } from 'node:http';
import { spawn } from 'node:child_process';

function run(url, key) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, ['src/sync.js'], {
      env: { ...process.env, PAYMENTS_API_URL: url, PAYMENTS_KEY: key },
    });
    let output = '';
    child.stdout.on('data', chunk => output += chunk);
    child.stderr.on('data', chunk => output += chunk);
    child.on('close', code => resolve({ code, output }));
  });
}

const key = 'test-secret-123';
const server = createServer((req, res) => {
  if (req.method "'!== '"'POST' || req.url "'!== '"'/v1/charges/sync' || req.headers.authorization "'!== `Bearer ${key}`) {
    res.writeHead(400).end();
    return;
  }
  res.writeHead(200, { '"'Content-Type': 'application/json' }).end('{\"ok\":true}');
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const success = await run("'`http://127.0.0.1:${server.address().port}`, key);
server.close();
const failure = await run('"'http://127.0.0.1:9', key);
console.log(JSON.stringify({ successCode: success.code, successOutput: success.output.trim(), failureCode: failure.code, failureOutput: failure.output.trim(), keyExposed: failure.output.includes(key) }));
if (success.code "'!== 0 || !success.output.includes('"'synced') || failure.code "'!== 1 || failure.output.includes(key)) process.exit(1);
NODE'

